"""Load a JSON config file, falling back to built-in defaults."""

from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)

DEFAULTS: dict[str, Any] = {
    "host": "127.0.0.1",
    "port": 8080,
    "debug": False,
    "log_level": "INFO",
    "timeout_seconds": 30,
}


class ConfigError(Exception):
    """Raised when a config file exists but cannot be used."""


def _merge(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:
    merged = dict(base)
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = _merge(merged[key], value)
        else:
            merged[key] = value
    return merged


def load_config(path: str | Path, defaults: dict[str, Any] | None = None) -> dict[str, Any]:
    """Return the config at `path` merged over `defaults`.

    A missing file is not an error: the defaults are returned unchanged.
    A file that exists but is unreadable or malformed raises ConfigError,
    since silently ignoring it would hide a real misconfiguration.
    """
    base = DEFAULTS if defaults is None else defaults
    path = Path(path)

    try:
        raw = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        logger.info("No config at %s; using defaults", path)
        return dict(base)
    except OSError as exc:
        raise ConfigError(f"cannot read {path}: {exc}") from exc

    try:
        parsed = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ConfigError(f"invalid JSON in {path}: {exc}") from exc

    if not isinstance(parsed, dict):
        raise ConfigError(f"{path} must contain a JSON object, got {type(parsed).__name__}")

    return _merge(base, parsed)
